(() => {
  'use strict';
  const L = window.LESSON, N = window.LESSON_NOTES;
  const P = N.presentation;
  const R = P.recall || {hint:'20 words from Day 1', eyebrow:'DAY +1 · CLOSED-BOOK REVIEW', title:'Recall yesterday. Then read today.', description:'20 expressions from Day 1. Retrieve the words without a word bank. Open each answer after your attempt and self-mark only what you recalled without looking.'};
  const app = document.querySelector('#app');
  const key = L.storageKey;
  const defaults = { read: [], saved: [], answers: {}, practice: {}, writing: '', challenge: '', speaking: {}, recall: {}, recalled: [], submitted: false };
  let state;
  try { state = { ...defaults, ...JSON.parse(localStorage.getItem(key) || '{}') }; } catch { state = { ...defaults }; }
  let current = 'overview', filter = 'all', search = '', timer = null, remaining = 0, wordOpenTimer = null;
  const lessonFolder = window.COURSE_VOCABULARY.find(item=>item.storageKey===key).folder;
  function syncSaved() {
    if(window.Wordbook.problem)return;
    const words=new Set(window.Wordbook.forLesson(lessonFolder).filter(e=>window.Wordbook.kind(e)==='word').flatMap(e=>[e.key,...e.sources.filter(s=>s.folder===lessonFolder).map(s=>window.Wordbook.normalize(s.selectedText))]));
    state.saved=L.vocabulary.filter(v=>words.has(window.Wordbook.normalize(v.word))).map(v=>v.id);
  }
  syncSaved();
  const icons = {
    book: '<path d="M3 4h6c2 0 3 1 3 3v14c0-2-2-3-4-3H3zM21 4h-6c-2 0-3 1-3 3v14c0-2 2-3 4-3h5z"/>',
    overview: '<rect x="3" y="3" width="7" height="7" rx="2"/><rect x="14" y="3" width="7" height="7" rx="2"/><rect x="3" y="14" width="7" height="7" rx="2"/><rect x="14" y="14" width="7" height="7" rx="2"/>',
    words: '<path d="M4 5h16v14H4zM7 9h6m-6 4h10M16 5v4"/>',
    grammar: '<path d="M8 4H4v16h4m8-16h4v16h-4M9 9l-2 3 2 3m6-6 2 3-2 3"/>',
    check: '<path d="m5 12 4 4L19 6"/>',
    exercise: '<rect x="5" y="4" width="14" height="17" rx="2"/><path d="M9 3h6v4H9zM9 12h6m-6 4h4"/>',
    pen: '<path d="m4 16-1 5 5-1L20 8l-4-4zM14 6l4 4"/>',
    mic: '<rect x="9" y="3" width="6" height="12" rx="3"/><path d="M5 11v1a7 7 0 0 0 14 0v-1M12 19v3m-4 0h8"/>',
    bookmark: '<path d="M6 3h12v18l-6-4-6 4z"/>',
    arrow: '<path d="M4 12h16m-6-6 6 6-6 6"/>',
    chevron: '<path d="m9 5 7 7-7 7"/>',
    menu: '<path d="M4 6h16M4 12h16M4 18h16"/>',
    close: '<path d="m6 6 12 12M6 18 18 6"/>',
    sound: '<path d="M4 9h4l5-4v14l-5-4H4zM17 8a6 6 0 0 1 0 8m3-11a10 10 0 0 1 0 14"/>',
    clock: '<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',
    search: '<circle cx="10" cy="10" r="6"/><path d="m15 15 6 6"/>',
    light: '<path d="M9 18h6m-5 3h4M8 14a6 6 0 1 1 8 0l-1 2H9z"/>',
    expand: '<path d="M8 3H3v5m13-5h5v5M3 16v5h5m13-5v5h-5"/>',
    reset: '<path d="M4 10a8 8 0 1 1 1 8M4 4v6h6"/>',
    layers: '<path d="m12 3 10 5-10 5L2 8zm-10 10 10 5 10-5M2 18l10 5 10-5"/>',
    download: '<path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/>'
  };
  const icon = (name, cls = '') => `<svg class="icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name] || icons.book}</svg>`;
  const esc = v => String(v ?? '').replace(/[&<>"']/g, c => ({ '&':'&amp;', '<':'&lt;', '>':'&gt;', '"':'&quot;', "'":'&#39;' }[c]));
  const inline = text => esc(text).replace(/\[([^\]]+)\]\((https?:\/\/[^)]+)\)/g, '<a class="source-link" href="$2" target="_blank" rel="noopener noreferrer">$1</a>').replace(/\*\*(.+?)\*\*/g, '<strong>$1</strong>').replace(/\*(.+?)\*/g, '<em>$1</em>');
  function markdown(text) {
    const lines = (text || '').split('\n'); let html = '', list = '', table = false;
    const endList = () => { if (list) { html += `</${list}>`; list = ''; } };
    for (const line of lines) {
      if (/^\|/.test(line)) {
        endList(); if (/^\|\s*-/.test(line)) continue;
        if (!table) { html += '<div class="table-wrap"><table>'; table = true; }
        html += '<tr>' + line.split('|').slice(1,-1).map(c=>`<td>${inline(c.trim())}</td>`).join('') + '</tr>'; continue;
      }
      if (table) { html += '</table></div>'; table = false; }
      const heading = line.match(/^(#{1,4}) (.+)/);
      const item = line.match(/^(?:- |(\d+)\. )(.+)/);
      if (item) { const kind = item[1] ? 'ol' : 'ul'; if (list !== kind) { endList(); list = kind; html += `<${kind}>`; } html += `<li>${inline(item[2])}</li>`; continue; }
      endList();
      if (heading) html += `<h${Math.min(heading[1].length+1,4)}>${inline(heading[2])}</h${Math.min(heading[1].length+1,4)}>`;
      else if (line.trim() && !/^={5,}/.test(line)) html += `<p>${inline(line)}</p>`;
    }
    endList(); if (table) html += '</table></div>'; return html;
  }
  function save() {
    syncSaved();
    try { localStorage.setItem(key, JSON.stringify(state)); } catch { toast('This browser cannot save your progress. Export your study notes to keep a copy.'); }
  }
  function toast(text) { const el = document.querySelector('#toast'); el.textContent = text; el.classList.add('visible'); clearTimeout(toast.timeout); toast.timeout=setTimeout(()=>el.classList.remove('visible'),3000); }
  const views = [
    ['overview','overview','Overview','Start here'],['reading','book','Reading','Explore A–J'],['vocabulary','words','Vocabulary','Words in context'],['grammar','grammar','Sentence lab','Structure and meaning'],['exercises','exercise','Practice','Check your understanding'],['writing','pen','Writing','Build an argument'],['speaking','mic','Speaking','Develop your ideas'],['review','bookmark','My review','Recall and revisit']
  ];
  if (L.recall.length) views.splice(1,0,['recall','reset','Daily recall',R.hint]);
  function shell() {
    app.innerHTML = `<div class="mobile-backdrop" data-action="close-nav"></div><aside class="sidebar" aria-label="Lesson navigation">
      <a class="brand" href="../index.html">${icon('book')}<span>passage<span class="brand-dot">.</span><small>Read a little. Understand more.</small></span></a>
      <button class="mobile-close icon-button" data-action="close-nav" aria-label="Close navigation">${icon('close')}</button>
      <div class="lesson-label"><span class="lesson-number">${String(L.day).padStart(2,'0')}</span><div>Daily IELTS reading<small>${L.date}</small></div></div>
      <div class="lesson-switcher" aria-label="Choose a lesson"><a class="library-link" href="../index.html">All lessons ${icon('arrow')}</a>${window.COURSE.lessons.map(lesson=>`<a href="../${lesson.folder}/index.html" ${lesson.day===L.day?'aria-current="page"':''}>Day ${lesson.day} · ${esc(lesson.shortTitle)}</a>`).join('')}</div><p class="nav-caption">THIS LESSON</p>
      <nav>${views.map(([id,ic,label,hint])=>`<a href="#${id}" data-view="${id}" class="nav-link">${icon(ic)}<span>${label}<small>${hint}</small></span>${id==='vocabulary'?'<span class="nav-count">30</span>':id==='grammar'?'<span class="nav-count">5</span>':''}</a>`).join('')}</nav>
      <a class="wb-lesson-link" href="../wordbook.html">${icon('bookmark')}<span>Wordbook<small>Words and sentences</small></span><span data-wb-count></span></a><div class="sidebar-foot"><div class="reading-progress"><span>Reading progress</span><strong id="read-count">${state.read.length} / 10</strong></div><div class="progress-track"><div id="read-progress" style="width:${state.read.length*10}%"></div></div><p>${icon('check')} Progress saved in this browser</p></div>
    </aside><div class="workspace"><header class="topbar"><button class="icon-button menu-button" data-action="open-nav" aria-label="Open lesson navigation" aria-expanded="false">${icon('menu')}</button><div class="breadcrumb"><span>IELTS Reading</span>${icon('chevron')}<strong id="breadcrumb-current">Overview</strong></div><div class="topbar-tools"><span class="level-tag">B2+ — C1</span><button class="text-button" data-action="source">${icon('book')}<span>Source material</span></button></div></header><main id="main" tabindex="-1"></main><footer class="page-footer"><span>passage. <span class="footer-sep">/</span> Read the language. Understand the world.</span><span>Lesson ${String(L.day).padStart(2,'0')} · ${P.footerTopic}</span></footer></div>
      <dialog id="detail-dialog" aria-labelledby="dialog-title"><div class="dialog-top"><span id="dialog-title"></span><button class="icon-button" data-action="close-dialog" aria-label="Close dialog">${icon('close')}</button></div><div id="dialog-content"></div></dialog><div id="toast" role="status" aria-live="polite"></div>`;
  }
  function pageHeading(eyebrow,title,description,extra='') { return `<div class="page-heading"><div><p class="eyebrow">${eyebrow}</p><h1>${title}</h1><p>${description}</p></div>${extra}</div>`; }
  const btn = (label, view, style='primary') => `<button class="button ${style}" data-action="navigate" data-target="${view}">${label}${icon('arrow')}</button>`;
  const figure = (index,caption,alt=caption) => index == null ? '' : `<figure class="lesson-figure"><button data-action="image" data-index="${index}" data-caption="${esc(caption)}" aria-label="Enlarge illustration: ${esc(caption)}"><img src="images/reference-${index}.webp" alt="${esc(alt)}" loading="lazy" width="1672" height="941">${icon('expand')}</button><figcaption>${esc(caption)} <span>Click to explore the full illustration</span></figcaption></figure>`;

  function overview() {
    return `<section class="hero"><div class="hero-copy"><p class="eyebrow"><span class="small-line"></span> ${P.topic}</p><h1>${P.heroTitle}</h1><p class="hero-subtitle">${P.subtitle}</p><p class="hero-description">${N.intro}</p><div class="hero-actions">${btn(L.recall.length?'Start closed-book recall':'Start reading',L.recall.length?'recall':'reading')}<button class="text-button" data-action="scroll" data-target="story-map">Explore the story ${icon('arrow')}</button></div><div class="hero-meta"><span>${icon('book')} 10 paragraphs</span><span>${icon('words')} 30 expressions</span><span>${icon('clock')} Two study sessions</span></div></div><figure class="hero-visual ${P.imageLayout}"><img src="${P.heroImage}" alt="${esc(P.heroAlt)}" width="1672" height="941" fetchpriority="high"><figcaption><span class="caption-kicker">${P.captionKicker}</span><span>${P.caption}</span></figcaption><span class="image-credit">Lesson illustration</span></figure></section>
      <section class="news-strip" aria-label="Lesson context"><div class="news-intro">${icon('layers')}<div><strong>${P.contextTitle}</strong><span>${P.contextDate}</span></div></div>${P.contextFacts.map(([value,label])=>`<div><strong>${value}</strong><span>${label}</span></div>`).join('')}<a href="#reading-${P.contextParagraph}">${P.contextLink}${icon('arrow')}</a></section>
      <section id="story-map" class="story-section"><div class="section-heading"><div><p class="eyebrow">THE BIG PICTURE</p><h2>${P.storyTitle}</h2></div><span class="subtle">${P.storyFlow}</span></div><div class="story-grid">${P.story.map(item=>`<a href="#reading-${item.target}" class="story-item"><span class="story-label">${item.label}</span><span class="story-art ${item.color||''}">${icon(item.icon)}</span><h3>${item.title}</h3><p>${item.description}</p><span class="story-link">${item.terms} ${icon('arrow')}</span></a>`).join('')}</div></section>
      <section class="learning-section"><div class="section-heading"><div><p class="eyebrow">YOUR LEARNING PATH</p><h2>Read it. Think it through. Use it.</h2></div><span class="subtle">Follow the original learning sequence</span></div><div class="learning-path">${[['reading','book','Reading','Original text, illustrations and explanations'],['vocabulary','words','Vocabulary','30 expressions · 10 core words'],['grammar','grammar','Sentence lab','5 ways to build an argument'],['exercises','exercise','Practice','15 reading + 30 vocabulary questions'],['writing','pen','Express your view','Writing and speaking']].map(([v,i,t,d])=>`<button data-action="navigate" data-target="${v}">${icon(i)}<strong>${t}</strong><span>${d}</span>${icon('chevron')}</button>`).join('')}</div></section><aside class="study-note">${icon('light')}<p>${P.studyNote}</p></aside>`;
  }
  function marked(text) {
    return text.split(/(\[[^\]]+\]\(https?:\/\/[^)]+\))/g).map(part=>/^\[[^\]]+\]\(https?:\/\//.test(part)?inline(part):highlightWords(part)).join('');
  }
  function highlightWords(text) {
    const words=L.vocabulary.slice().sort((a,b)=>b.word.length-a.word.length);
    const pattern=new RegExp('\\b('+words.map(w=>w.word.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')).join('|')+')\\b','gi');
    let html='',last=0;
    for(const m of text.matchAll(pattern)){const v=words.find(w=>w.word.toLowerCase()===m[0].toLowerCase());html+=esc(text.slice(last,m.index))+`<button class="word-mark ${v.core?'core-word':''}" data-action="word" data-id="${v.id}" aria-label="See the meaning of ${esc(v.word)}">${esc(m[0])}</button>`;last=m.index+m[0].length;}
    return html+esc(text.slice(last));
  }
  function reading() {
    return pageHeading('READ THE STORY',P.readingTitle,'Read the original A–J paragraphs. Click highlighted words for meanings and open explanations when you need them.',`<button class="button secondary compact" data-action="explanations">${icon('layers')} Expand all explanations</button>`)+
      `<div class="reading-toolbar"><div class="paragraph-jumps" aria-label="Jump to a paragraph">${L.paragraphs.map(p=>`<a href="#reading-${p.id}" class="${state.read.includes(p.id)?'done':''}">${p.id}</a>`).join('')}</div><span class="subtle">${icon('words')} Select a word or sentence to save</span></div><div class="reading-layout"><div class="article-stream">${L.paragraphs.map((p,i)=>{const n=N.paragraphs[i];return `<article class="paragraph" id="paragraph-${p.id}"><div class="paragraph-heading"><div class="paragraph-letter">${p.id}</div><div><span class="paragraph-tag">${n.tag}</span><h2>${n.title}</h2></div><button class="read-button ${state.read.includes(p.id)?'is-read':''}" data-action="read" data-id="${p.id}" aria-pressed="${state.read.includes(p.id)}">${icon('check')}<span>${state.read.includes(p.id)?'Read':'Mark as read'}</span></button></div><p class="english-passage" lang="en">${marked(p.text)}</p><div class="takeaway">${icon('light')}<p>${n.takeaway}</p></div>${diagram(p.id)}<details class="explanation"><summary>Plain-English explanation and quick check ${icon('chevron')}</summary><div class="explanation-content"><p>${n.explanation}</p><div class="retrieval"><strong>Think about it · ${n.question}</strong><details><summary>Show the reasoning</summary><p>${n.answer}</p></details></div></div></details>${figure(n.image,n.title+' · Concept illustration',n.imageAlt)}</article>`;}).join('')}<div class="next-section"><div><span class="eyebrow">NEXT · VOCABULARY</span><h3>Make the expressions you just read your own</h3></div>${btn('Explore vocabulary','vocabulary')}</div></div><aside class="reading-aside"><p class="eyebrow">READING COMPASS</p><h3>Read the words.<br>Question the claims.</h3><div class="evidence-key"><span class="evidence-dot blue"></span><div><strong>Facts and definitions</strong><p>${P.facts}</p></div></div><div class="evidence-key"><span class="evidence-dot amber"></span><div><strong>Interpretation and possibility</strong><p>May, could and if signal conditional claims.</p></div></div><div class="evidence-key"><span class="evidence-dot teal"></span><div><strong>Examples and viewpoints</strong><p>${P.examples}</p></div></div><blockquote>${P.compass.join('<br>')}</blockquote><p class="subtle">Three questions to keep asking</p></aside></div>`;
  }
  function diagram(id) {
    if (N.diagrams) return conceptDiagram(id);
    if(id==='B')return `<div class="explainer"><div class="explainer-title"><span>See what a revision changes</span><span class="subtle">Passage figures · jobs</span></div><div class="revision-table"><div><strong>June</strong><span>20,000 ${icon('arrow')} <b>31,000</b></span><em>+11,000</em></div><div><strong>July</strong><span>−23,000 ${icon('arrow')} <b>+21,000</b></span><em>+44,000</em></div></div><p>Combined upward revision: <strong>55,000</strong>. July also changed from a reported loss to a gain.</p></div>`;
    if(id==='C')return `<div class="explainer"><div class="explainer-title"><span>One month, different directions</span><span class="subtle">Selected industries from the passage</span></div><div class="sector-chart">${[['Food services',59000],['Local government education',42000],['Information',-23000]].map(([name,value])=>`<div class="sector-row"><span>${name}</span><div class="bar-axis"><div class="sector-bar ${value<0?'negative':''}" style="width:${Math.abs(value)/59000*65}%"></div></div><strong class="${value<0?'negative-text':''}">${value>0?'+':'−'}${Math.abs(value).toLocaleString('en')}</strong></div>`).join('')}</div><p>These are selected industries, not the whole economy. Their sum is not the national total.</p></div>`;
    if(id==='D')return `<div class="explainer"><div class="explainer-title"><span>Who is in the labour force?</span><span class="subtle">Choose a situation to see the category</span></div><div class="people-options">${[['full','Working full time','Employed'],['search','Without work, actively searching','Unemployed'],['part','Working part time, wants more hours','Employed'],['discouraged','Wants work, has given up searching','Outside the labour force']].map(([v,t,a])=>`<button data-action="classify" data-value="${v}">${icon('book')}<span>${t}</span></button>`).join('')}</div><p id="classification-result" role="status">Having a job and having enough work are different questions.</p></div>`;
    if(id==='E')return `<div class="explainer purchasing-lab"><div class="explainer-title"><span>Try the purchasing power calculator</span><span class="subtle">A hypothetical scenario</span></div><div class="slider-grid"><label for="wage-range">Wage growth <output id="wage-label">2%</output><input id="wage-range" type="range" min="0" max="12" value="2" step="1"></label><label for="price-range">Price increase <output id="price-label">4%</output><input id="price-range" type="range" min="0" max="12" value="4" step="1"></label></div><div class="purchasing-result"><span>Change in real purchasing power</span><strong id="real-change">−1.92%</strong><span id="real-meaning">Pay has risen, but it buys less.</span></div><p>Calculation · (1 + wage growth) ÷ (1 + price growth) − 1</p></div>`;
    if(id==='G')return `<div class="explainer"><div class="explainer-title"><span>Follow the policy transmission</span><span class="subtle">A possible mechanism</span></div><div class="policy-flow"><span>Higher interest rates</span>${icon('arrow')}<span>Higher borrowing costs</span>${icon('arrow')}<span>Less spending and investment</span>${icon('arrow')}<span>Lower demand</span></div><div class="policy-outcomes"><span>May ease price pressure</span><span>May also weaken hiring</span></div><p>The sentence uses <strong>may</strong> and <strong>potentially</strong> to preserve uncertainty about the outcomes.</p></div>`;
    return '';
  }

  function conceptDiagram(id) {
    const d=N.diagrams[id];if(!d)return '';
    let body='';
    if(d.type==='compare')body=`<div class="concept-comparison">${d.items.map(([title,text])=>`<div><strong>${title}</strong><p>${text}</p></div>`).join('')}</div>`;
    if(d.type==='choices')body=`<div class="concept-options">${d.options.map(([title],i)=>`<button class="${i===0?'selected':''}" data-action="concept" data-diagram="${id}" data-index="${i}" aria-pressed="${i===0}">${title}${icon('arrow')}</button>`).join('')}</div><p id="concept-${id}" class="concept-result" role="status">${d.options[0][1]}</p>`;
    if(d.type==='coverage')body=`<div class="coverage-lab">${[90,80,40].map((value,i)=>`<label for="coverage-${i}"><span>Community ${String.fromCharCode(65+i)} <output id="coverage-value-${i}">${value}%</output></span><input type="range" id="coverage-${i}" data-coverage="${i+1}" min="0" max="100" value="${value}" step="5"><span class="coverage-track"><span id="coverage-bar-${i}" style="width:${value}%"></span><i title="70% reference target"></i></span></label>`).join('')}</div><div class="coverage-summary"><span>Combined coverage <strong id="coverage-average">70%</strong></span><span id="coverage-gap" role="status">1 community below the 70% reference</span></div><p>${d.note}</p>`;
    return `<div class="explainer"><div class="explainer-title"><span>${d.title}</span><span class="subtle">${d.subtitle}</span></div>${body}</div>`;
  }
  function updateCoverage(){
    const values=[...document.querySelectorAll('[data-coverage]')].map((el,i)=>{const v=Number(el.value);document.querySelector('#coverage-value-'+i).textContent=v+'%';document.querySelector('#coverage-bar-'+i).style.width=v+'%';return v;});
    document.querySelector('#coverage-average').textContent=(values.reduce((a,b)=>a+b,0)/values.length).toFixed(1).replace('.0','')+'%';
    const gaps=values.filter(v=>v<70).length;
    document.querySelector('#coverage-gap').textContent=gaps?`${gaps} ${gaps===1?'community':'communities'} below the 70% reference`:'All communities reach the reference; the percentage alone does not guarantee protection.';
  }
  function recall(){
    return pageHeading(R.eyebrow,R.title,R.description,`<span id="recall-progress" class="subtle">${state.recalled.length} / 20 self-marked recalled</span>`)+`<div class="recall-list">${L.recall.map(q=>`<article class="recall-card"><label for="recall-${q.id}"><span class="question-number">R${q.id}</span><span>${inline(q.question)}</span></label><textarea id="recall-${q.id}" data-recall="${q.id}" rows="2" placeholder="Retrieve the word or write your sentence.">${esc(state.recall[q.id]||'')}</textarea><details><summary>Compare with the answer and usage note</summary><p>${inline(q.explanation)}</p><button class="button secondary compact" data-action="recall-mark" data-id="${q.id}" aria-pressed="${state.recalled.includes(q.id)}">${state.recalled.includes(q.id)?'Recalled without looking':'Mark recalled without looking'}</button></details></article>`).join('')}</div><div class="next-section"><div><span class="eyebrow">NEXT · TODAY'S READING</span><h3>A new story. Thirty new expressions.</h3></div>${btn('Read today’s passage','reading')}</div>`;
  }
  function vocabulary() {
    return pageHeading('WORDS IN CONTEXT','Learn words inside the story','Read the context, then recall the collocation. Core words carry a star; bookmarked expressions appear in My review.')+`<div class="vocab-toolbar"><label class="search-box">${icon('search')}<input id="vocab-search" type="search" placeholder="Search words, meanings or collocations" value="${esc(search)}" aria-label="Search vocabulary"></label><div class="filter-buttons">${[['all','All 30'],['core','Core 10'],['saved','Saved']].map(([v,t])=>`<button data-action="filter" data-value="${v}" class="${filter===v?'active':''}" aria-pressed="${filter===v}">${t}</button>`).join('')}</div></div><div id="vocab-list">${wordList()}</div><details class="source-fold"><summary>Spaced-repetition plan from the lesson</summary><div class="prose">${markdown(L.sections['SPACED-REPETITION REVIEW — 20 WORDS'])}${markdown(L.sections['VOCABULARY REVIEW LEDGER'])}</div></details><div class="next-section"><div><span class="eyebrow">NEXT · SENTENCE LAB</span><h3>Go beyond words to the logic of a sentence</h3></div>${btn('Explore sentence patterns','grammar')}</div>`;
  }
  function wordList() {
    const list=L.vocabulary.filter((v,i)=>(filter==='all'||filter==='core'&&v.core||filter==='saved'&&state.saved.includes(v.id))&&`${v.word} ${N.vocabulary[i]} ${v.Collocation} ${v.Definition}`.toLowerCase().includes(search.toLowerCase()));
    return `<p class="result-count">${list.length} expressions${search?' · Search results':''}</p><div class="vocab-grid">${list.length?list.map(v=>wordCard(v)).join(''):'<div class="empty-state">'+icon('bookmark')+'<h3>No matching expressions yet</h3><p>Try another search term, or bookmark a word to add it to your review.</p></div>'}</div>`;
  }
  function wordCard(v) {
    const i=Number(v.id)-1;
    return `<article class="vocab-card"><div class="vocab-top"><span class="vocab-id">${v.id} ${v.core?'<span class="core-tag">★ Core</span>':''}</span><button class="icon-button save-word ${state.saved.includes(v.id)?'saved':''}" data-action="save-word" data-id="${v.id}" aria-label="${state.saved.includes(v.id)?'Remove bookmark':'Bookmark'} ${esc(v.word)}" aria-pressed="${state.saved.includes(v.id)}">${icon('bookmark')}</button></div><h2 lang="en">${esc(v.word)} <button class="pronounce icon-button" data-action="speak" data-id="${v.id}" aria-label="Read aloud: ${esc(v.word)}">${icon('sound')}</button></h2><p class="ipa" lang="en">${esc(v['IPA / part of speech'])}</p><p class="word-gloss">${N.vocabulary[i]}</p><p class="definition" lang="en">${inline(v.Definition)}</p><div class="collocation"><span>Common collocation</span><strong lang="en">${esc(v.Collocation)}</strong></div><details><summary>Article sentence, examples and usage ${icon('chevron')}</summary><div class="word-details"><p class="field-label">IN THE ARTICLE</p><p lang="en">${esc(v.Article)}</p><p class="field-label">CONTEXT</p><p lang="en">${esc(v['In context'])}</p><p class="field-label">TRY IT ELSEWHERE</p><p lang="en">${esc(v['Additional example'])}</p><p class="field-label">WORD FAMILY</p><p lang="en">${esc(v.Family)}</p><div class="learner-note">${icon('light')}<p lang="en">${inline(v['Learner note'])}</p></div></div></details></article>`;
  }
  function grammar() {
    return pageHeading('SENTENCE LAB','Read the structure. Understand the limits.','Five original sentences, five ways to reason. Select a sentence chunk to explore its role in the argument.')+`<div class="grammar-list">${L.grammar.map((g,i)=>{const n=N.grammar[i];return `<article class="grammar-card"><div class="grammar-title"><span class="grammar-number">0${i+1}</span><div><p class="eyebrow">${n.label}</p><h2>${n.title}</h2></div>${((Object.keys(g.fields)[0] || '').split(', ')[1] || g.paragraph) ? `<span class="grammar-origin">Paragraph ${esc((Object.keys(g.fields)[0] || '').split(', ')[1] || g.paragraph)}</span>` : ''}</div><div class="sentence-chunks" lang="en">${n.chunks.map((c,j)=>`<button class="chunk chunk-${j}" data-action="chunk" data-grammar="${i}" data-index="${j}" aria-label="${esc(n.roles[j])}: ${esc(c)}"><span>${esc(c)}</span><small>${n.roles[j]}</small></button>`).join('')}</div><p class="grammar-tip" id="grammar-tip-${i}">${n.tip}</p><details><summary>Full grammar explanation and transfer example ${icon('chevron')}</summary><div class="prose">${Object.entries(g.fields).map(([k,v])=>`<p><strong>${esc(k)}</strong><br>${inline(v)}</p>`).join('')}</div></details></article>`;}).join('')}</div><div class="next-section"><div><span class="eyebrow">NEXT · PRACTICE</span><h3>Return to the passage and test your understanding</h3></div>${btn('Start practice','exercises')}</div>`;
  }
  function exercises() {
    return pageHeading('PUT YOUR READING TO WORK','Answer first. Then examine the evidence.','Allow ' + (P.readingTime || '22–25 minutes') + '. Base answers on paragraphs A–J, not on the vocabulary explanations.')+`<div class="practice-switch"><a href="#reading-questions">Reading comprehension <span>15 questions</span></a><a href="#vocabulary-practice">Vocabulary practice <span>30 questions</span></a></div><section id="reading-questions"><div class="section-heading"><div><p class="eyebrow">READING CHECK</p><h2>Where is the evidence?</h2></div><span id="answer-progress" class="subtle">Answered ${Object.values(state.answers).filter(Boolean).length} / 15</span></div><form id="reading-form">${L.reading.map((q,i)=>`${i===0||q.type!==L.reading[i-1].type?`<div class="question-group"><span>${q.type}</span><p>${q.instruction}</p></div>${q.type==='Summary completion'?`<div class="summary-context">${inline(L.summary)}</div>`:''}`:''}<fieldset class="question" id="question-${q.id}"><legend><span class="question-number">${q.id}</span>${inline(q.question)}</legend>${q.options.length?`<div class="answer-options ${q.type.includes('Not Given')?'tf-options':''}">${q.options.map(o=>`<label><input type="radio" name="q${q.id}" value="${esc(o.value)}" ${state.answers[q.id]===o.value?'checked':''}><span>${q.type.includes('Not Given')?'':`<b>${o.value}</b>`}${esc(o.text)}</span></label>`).join('')}</div>`:`<input class="answer-input" type="text" name="q${q.id}" value="${esc(state.answers[q.id]||'')}" placeholder="No more than two words" aria-label="Answer to question ${q.id}" autocomplete="off">`}<div class="feedback" id="feedback-${q.id}" ${state.submitted?'':'hidden'}>${state.submitted?answerFeedback(q):''}</div></fieldset>`).join('')}<div class="submit-row"><button class="button primary" type="submit">Check my answers ${icon('check')}</button><button class="button secondary" type="button" data-action="reset-reading">Try again ${icon('reset')}</button><span id="reading-score" role="status">${state.submitted?scoreText():''}</span></div></form></section><section id="vocabulary-practice" class="vocab-practice-section"><div class="section-heading"><div><p class="eyebrow">VOCABULARY PRACTICE</p><h2>From recognising words to using them</h2></div><span class="subtle">All 30 new expressions</span></div><p class="section-description">Try without the word list. Compare sentence transformations with the model answers; more than one phrasing may be possible.</p>${['A','B','C','D','E'].map((group,i)=>`<details class="practice-group" ${i===0?'open':''}><summary><span class="practice-group-letter">${group}</span><span>${['Fill in the blanks','Synonyms and paraphrasing','Collocations','Word formation','Sentence transformation'][i]} <small>${[10,5,5,5,5][i]} questions</small></span>${icon('chevron')}</summary><div class="practice-group-content">${L.practice.filter(q=>q.id[0]===group).map(q=>`<div class="vocab-question"><label for="practice-${q.id}"><strong>${q.id}</strong> ${inline(q.question)}</label>${group==='E'?`<textarea id="practice-${q.id}" data-practice="${q.id}" placeholder="Write a complete sentence using the capitalised expression unchanged.">${esc(state.practice[q.id]||'')}</textarea>`:`<input class="answer-input" id="practice-${q.id}" data-practice="${q.id}" value="${esc(state.practice[q.id]||'')}" placeholder="Enter a word or phrase" autocomplete="off">`}<details><summary>Show the model answer</summary><p class="practice-answer" lang="en">${inline(q.explanation)}</p></details></div>`).join('')}</div></details>`).join('')}</section>`;
  }
  const normalize = v => v.toLowerCase().trim().replace(/\s+/g,' ');
  function answerFeedback(q) { const correct=normalize(state.answers[q.id]||'')===normalize(q.answer);return `<div class="answer-result ${correct?'correct':'incorrect'}">${icon(correct?'check':'light')}<strong>${state.answers[q.id]?correct?'Correct':'Check the evidence again':'Not answered'} · ${esc(q.answer)}</strong>${q.paragraph?`<a href="#reading-${q.paragraph}">Go to paragraph ${q.paragraph} ${icon('arrow')}</a>`:'<span>The passage does not state this claim.</span>'}</div><p lang="en">${inline(q.explanation)}</p>`; }
  function scoreText() { return `${L.reading.filter(q=>normalize(state.answers[q.id]||'')===normalize(q.answer)).length} / 15 · Practice score`; }
  function writing() {
    return pageHeading('WRITING WORKSHOP','Turn your reading into a reasoned view',`Task 2 · ${P.writingType}. Write your own essay before consulting the plan.`)+`<section class="writing-prompt"><span class="eyebrow">IELTS WRITING TASK 2</span><p lang="en">${P.writingPrompt}</p><p lang="en"><strong>${P.writingQuestion}</strong></p><div class="prompt-meta"><span>${icon('clock')} Allow 40 minutes</span><span>${icon('pen')} At least 250 words</span></div></section><div class="writing-layout"><div><div class="editor-heading"><h2>Your draft</h2><span class="save-status" id="writing-save-status">${state.writing?'Saved in this browser':'Saves automatically as you type'}</span></div><label class="sr-only" for="writing-editor">Task 2 essay draft</label><textarea id="writing-editor" class="writing-editor" placeholder="State your position. What reasons and examples support it?\n\nWrite your own essay here…" spellcheck="true">${esc(state.writing)}</textarea><div class="editor-footer"><span id="writing-count">${wordCount(state.writing)} words</span><button class="text-button" data-action="export-writing">${icon('download')} Export draft</button></div><details class="source-fold"><summary>Full writing plan and language patterns</summary><div class="prose">${markdown(L.sections['IELTS WRITING TASK 2'].split('### WRITING TASK 2 PLANNING')[1])}</div></details></div><aside class="writing-guide"><p class="eyebrow">BUILD YOUR ARGUMENT</p><h3>Give each paragraph a purpose</h3><ol>${P.writingGuide.map(([title,description])=>`<li><strong>${title}</strong><p>${description}</p></li>`).join('')}</ol><div class="guide-language"><strong>Use these naturally</strong><p>${P.writingWords.join('<br>')}</p></div></aside></div>${P.challengeMode==='writing'?challenge():''}`;
  }
  function challenge() { return `<section class="challenge-section"><div><p class="eyebrow">THE ONE-MINUTE CHALLENGE</p><h2>One minute to organise your thoughts</h2><p lang="en">${P.challengePrompt}</p><p>${P.challengeInstructions}</p><div class="challenge-words">${P.challengeWords.map(w=>`<span data-challenge-word="${w}">${w}</span>`).join('')}</div><button class="button secondary compact" data-action="timer" data-seconds="60">${icon('clock')} Start 1-minute planning</button><output class="timer-output" id="challenge-timer-output" aria-live="polite"></output>${P.challengeMode==='speaking'?`<button class="text-button" data-action="timer" data-seconds="90">${icon('mic')} Start 90-second speaking</button>`:''}</div><div><label for="challenge-editor">${P.challengeMode==='speaking'?'Your speaking keywords':'Your short response'}</label><textarea id="challenge-editor" placeholder="${esc(P.challengePlaceholder)}">${esc(state.challenge)}</textarea><div class="editor-footer"><span id="challenge-count">${wordCount(state.challenge)} words</span><span id="challenge-used"></span></div></div></section>`; }
  function speaking() {
    return pageHeading('SPEAKING PART 3','Share a view. Explain your reasons.','Build your answer with a point, an explanation, and an example or qualification. Speak first, then open the hints. Use the ideas rather than memorising them.')+`<div class="speaking-method"><span><b>Point</b>Your position</span>${icon('arrow')}<span><b>Why</b>Reasons and mechanisms</span>${icon('arrow')}<span><b>Example / condition</b>An example or qualification</span></div><div class="speaking-list">${L.speaking.map((s,i)=>`<article class="speaking-card"><span class="grammar-number">0${i+1}</span><div><h2 lang="en">${esc(s.title.replace(/^\d+\. /,''))}</h2><details><summary>Show ideas and useful language ${icon('chevron')}</summary><p><strong>Ideas</strong><br>${esc(s.fields['Useful ideas'])}</p><p><strong>Language</strong><br>${esc(s.fields['Useful language'])}</p></details><label for="speaking-${i}">Jot down keywords</label><textarea id="speaking-${i}" data-speaking="${i}" placeholder="Note keywords rather than a complete script.">${esc(state.speaking[i]||'')}</textarea></div><button class="button secondary compact" data-action="timer" data-seconds="120" data-question="${i+1}">${icon('clock')} Practise for 2 minutes</button></article>`).join('')}</div><div class="speaking-timer"><output id="timer-output" aria-live="polite">Choose a question to start practising.</output><button class="text-button" data-action="stop-timer">Stop timer</button></div>${P.challengeMode==='speaking'?challenge():''}`;
  }
  function review() {
    const words=L.vocabulary.filter(v=>state.saved.includes(v.id));
    const collection=window.Wordbook.forLesson(lessonFolder);
    const shared=`<section class="wb-course-review"><p class="eyebrow">YOUR SHARED WORDBOOK</p><h2>${collection.length} ${collection.length===1?'entry':'entries'} from this lesson</h2><p>Words and sentences you collect stay together across every lesson.</p><a class="text-button" href="../wordbook.html?lesson=${lessonFolder}">Open this lesson’s words →</a><div class="wb-review-list">${collection.map(e=>`<button data-wb="edit" data-id="${esc(e.id)}"><strong>${esc(e.term)}</strong><span>${esc(e.definition||(window.Wordbook.kind(e)==='sentence'?'Add your understanding or notes':'Meaning needed'))}</span></button>`).join('')}</div></section>`;
    return pageHeading('MAKE IT STICK','Keep what matters for next time','Bookmarks build your review list; reading markers track your progress. Use practice to judge how well you know each expression.',`<button class="button secondary compact" data-action="export-notes">${icon('download')} Export study notes</button>`)+`<div class="review-summary"><div><strong>${state.read.length}<small> / 10</small></strong><span>Paragraphs read</span></div><div><strong>${words.length}<small> / 30</small></strong><span>Words bookmarked</span></div><div><strong>${Object.values(state.answers).filter(Boolean).length}<small> / 15</small></strong><span>Reading questions answered</span></div><div><strong>${wordCount(state.writing)}</strong><span>Essay draft words</span></div></div>${shared}<div class="section-heading"><div><p class="eyebrow">YOUR WORD COLLECTION</p><h2>Recall these expressions next time</h2></div>${words.length?'<button class="text-button" data-action="flashcards">Start recall '+icon('arrow')+'</button>':''}</div><div class="vocab-grid">${words.length?words.map(wordCard).join(''):`<div class="empty-state">${icon('bookmark')}<h3>Start with a word you want to remember</h3><p>Bookmark a word on the vocabulary page or open a highlighted expression in the passage.</p>${btn('Choose some expressions','vocabulary')}</div>`}</div><details class="source-fold"><summary>Today’s recap · Lesson summary</summary><div class="prose">${markdown(L.sections['TODAY YOU LEARNED'])}</div></details><details class="source-fold"><summary>Spaced repetition · Lesson ledger and schedule</summary><div class="prose">${markdown(L.sections['VOCABULARY REVIEW LEDGER'])}</div></details>`;
  }
  const renderers={overview,reading,vocabulary,grammar,exercises,writing,speaking,review,recall};
  function navigate(view,paragraph,shouldFocus=false) {
    if(!renderers[view])view='overview';
    if(current!==view || !document.querySelector('#main').children.length) {
      stopTimer(false);current=view;document.querySelector('#main').innerHTML=renderers[view]();
      document.querySelectorAll('[data-view]').forEach(el=>{const active=el.dataset.view===view;el.classList.toggle('active',active);if(active)el.setAttribute('aria-current','page');else el.removeAttribute('aria-current');});
      document.querySelector('#breadcrumb-current').textContent=views.find(v=>v[0]===view)[2];
      document.title=`${views.find(v=>v[0]===view)[2]} · ${L.title} · Passage`;
      window.scrollTo(0,0);if(shouldFocus)document.querySelector('#main').focus({preventScroll:true});
    }
    closeNav();
    if(paragraph) { const target=document.querySelector('#paragraph-'+paragraph);if(target)target.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'}); }
    if(view==='writing'||view==='speaking')updateChallenge();
  }
  function route(focus=true){ const hash=location.hash.slice(1)||'overview';const m=hash.match(/^reading-([A-J])$/);if(m)navigate('reading',m[1],focus);else if(['reading-questions','vocabulary-practice'].includes(hash)){navigate('exercises',null,focus);document.getElementById(hash).scrollIntoView();}else navigate(hash,null,focus); }
  function go(view){if(location.hash==='#'+view)navigate(view);else location.hash=view;}
  function closeNav(){document.body.classList.remove('nav-open');document.querySelector('.menu-button').setAttribute('aria-expanded','false');}
  function openDialog(title,html,cls='') {const d=document.querySelector('#detail-dialog');d.className=cls;document.querySelector('#dialog-title').textContent=title;document.querySelector('#dialog-content').innerHTML=html;d.showModal();}
  function openWord(id){const v=L.vocabulary.find(v=>v.id===id);openDialog('Vocabulary',wordCard(v));}
  function wordCount(text){return(text.match(/[A-Za-z]+(?:['’-][A-Za-z]+)*/g)||[]).length;}
  function updateChallenge(){const text=state.challenge.toLowerCase();let count=0;document.querySelectorAll('[data-challenge-word]').forEach(el=>{const used=new RegExp('\\b'+el.dataset.challengeWord+'\\b','i').test(text);el.classList.toggle('used',used);if(used)count++;});const out=document.querySelector('#challenge-used');if(out)out.textContent=`Target expressions ${count} / 5${new RegExp(P.qualification,'i').test(text)?' · Qualification included':''}`;}
  function download(filename,text){const url=URL.createObjectURL(new Blob([text],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
  function stopTimer(message=true){clearInterval(timer);timer=null;if(message)document.querySelectorAll('.timer-output,.speaking-timer output').forEach(out=>out.textContent='Timer stopped');}
  function startTimer(seconds,question){stopTimer(false);remaining=seconds;const tick=()=>{document.querySelectorAll('.timer-output,.speaking-timer output').forEach(out=>out.textContent=(question?`Question ${question} · `:'')+`${String(Math.floor(remaining/60)).padStart(2,'0')}:${String(remaining%60).padStart(2,'0')}`);};tick();timer=setInterval(()=>{remaining--;tick();if(remaining<=0){stopTimer(false);document.querySelectorAll('.timer-output,.speaking-timer output').forEach(out=>out.textContent=seconds===60?(P.challengeMode==='speaking'?'Planning time is up. Start speaking.':'Planning time is up. Start writing.'):'Time is up. Review your point and example.');toast('Timer complete');}},1000);}
  function flashcard(index=0,revealed=false){const list=L.vocabulary.filter(v=>state.saved.includes(v.id));if(!list.length)return;const v=list[index%list.length];openDialog('Vocabulary recall',`<div class="flashcard"><p class="eyebrow">${index%list.length+1} / ${list.length} · Recall the meaning and a collocation first</p><h2 lang="en">${v.word}</h2>${revealed?`<p class="word-gloss">${N.vocabulary[Number(v.id)-1]}</p><p lang="en">${v.Definition}</p><strong lang="en">${v.Collocation}</strong>`:'<p class="subtle">Can you use it in a sentence of your own?</p>'}<div class="flashcard-actions">${revealed?`<button class="button primary" data-action="flash-next" data-index="${index+1}">Next expression ${icon('arrow')}</button>`:`<button class="button primary" data-action="flash-reveal" data-index="${index}">Reveal meaning and collocation</button>`}</div></div>`);}
  app.addEventListener('click',event=>{
    if(window.getSelection()?.toString().trim() && event.target.closest('.word-mark,.chunk'))return;
    const el=event.target.closest('[data-action]');if(!el)return;const action=el.dataset.action;
    if(action==='navigate')go(el.dataset.target);
    else if(action==='scroll')document.getElementById(el.dataset.target)?.scrollIntoView({behavior:'smooth'});
    else if(action==='open-nav'){document.body.classList.add('nav-open');el.setAttribute('aria-expanded','true');document.querySelector('.mobile-close').focus();}
    else if(action==='close-nav')closeNav();
    else if(action==='close-dialog')document.querySelector('#detail-dialog').close();
    else if(action==='word'){
      clearTimeout(wordOpenTimer);
      if(event.detail===0)openWord(el.dataset.id);
      else wordOpenTimer=setTimeout(()=>{if(!window.getSelection()?.toString().trim()&&el.isConnected)openWord(el.dataset.id);},300);
    }
    else if(action==='concept'){const d=N.diagrams[el.dataset.diagram];document.querySelector('#concept-'+el.dataset.diagram).textContent=d.options[Number(el.dataset.index)][1];document.querySelectorAll('[data-diagram="'+el.dataset.diagram+'"]').forEach(b=>{b.classList.toggle('selected',b===el);b.setAttribute('aria-pressed',b===el);});}
    else if(action==='recall-mark'){const id=el.dataset.id;state.recalled=state.recalled.includes(id)?state.recalled.filter(v=>v!==id):[...state.recalled,id];save();el.setAttribute('aria-pressed',state.recalled.includes(id));el.textContent=state.recalled.includes(id)?'Recalled without looking':'Mark recalled without looking';document.querySelector('#recall-progress').textContent=state.recalled.length+' / 20 self-marked recalled';}

    else if(action==='read'){const id=el.dataset.id;state.read=state.read.includes(id)?state.read.filter(x=>x!==id):[...state.read,id];save();const done=state.read.includes(id);el.classList.toggle('is-read',done);el.setAttribute('aria-pressed',done);el.querySelector('span').textContent=done?'Read':'Mark as read';document.querySelector('#read-count').textContent=`${state.read.length} / 10`;document.querySelector('#read-progress').style.width=state.read.length*10+'%';document.querySelectorAll(`a[href="#reading-${id}"]`).forEach(a=>a.classList.toggle('done',done));}
    else if(action==='save-word'){try{const linked=window.Wordbook.togglePreset(lessonFolder,el.dataset.id);toast(linked?'Added to wordbook':'Removed from this lesson’s bookmarks. Kept in your wordbook.');}catch(error){toast(error.message);}}
    else if(action==='filter'){filter=el.dataset.value;document.querySelectorAll('[data-action="filter"]').forEach(b=>{b.classList.toggle('active',b===el);b.setAttribute('aria-pressed',b===el);});document.querySelector('#vocab-list').innerHTML=wordList();}
    else if(action==='speak'){if(!('speechSynthesis' in window)){toast('Speech is not supported in this browser. Use the IPA pronunciation guide.');return;}speechSynthesis.cancel();const utterance=new SpeechSynthesisUtterance(L.vocabulary.find(v=>v.id===el.dataset.id).word);utterance.lang='en-GB';utterance.rate=.85;utterance.onerror=()=>toast('Speech is unavailable right now. Use the IPA pronunciation guide.');speechSynthesis.speak(utterance);}
    else if(action==='image')openDialog(el.dataset.caption,`<img class="full-image" src="images/reference-${el.dataset.index}.webp" alt="${esc(el.dataset.caption)}">`,'image-dialog');
    else if(action==='explanations'){const ds=[...document.querySelectorAll('.explanation')];const open=ds.some(d=>!d.open);ds.forEach(d=>d.open=open);el.innerHTML=icon('layers')+(open?' Collapse all explanations':' Expand all explanations');}
    else if(action==='chunk'){document.querySelectorAll(`[data-grammar="${el.dataset.grammar}"]`).forEach(b=>b.classList.toggle('selected',b===el));const n=N.grammar[el.dataset.grammar];document.querySelector('#grammar-tip-'+el.dataset.grammar).textContent=n.roles[el.dataset.index]+' · '+n.tip;}
    else if(action==='classify'){const data={full:'Employed and in the labour force.',search:'Unemployed and in the labour force, assuming availability for work and the official active-search criteria are met.',part:'Employed and in the labour force. Wanting more hours but being unable to obtain them may indicate underemployment.',discouraged:'A discouraged worker: outside the labour force and not included in the official unemployment count.'};document.querySelector('#classification-result').textContent=data[el.dataset.value];document.querySelectorAll('[data-action="classify"]').forEach(b=>b.classList.toggle('selected',b===el));}
    else if(action==='reset-reading'){state.answers={};state.submitted=false;save();document.querySelector('#main').innerHTML=exercises();}
    else if(action==='timer')startTimer(Number(el.dataset.seconds),el.dataset.question);
    else if(action==='stop-timer')stopTimer();
    else if(action==='export-writing')download(`lesson-${String(L.day).padStart(2,'0')}-writing.txt`,L.title+'\n\nTASK 2\n'+state.writing+'\n\nONE-MINUTE CHALLENGE\n'+state.challenge);
    else if(action==='export-notes')download(`lesson-${String(L.day).padStart(2,'0')}-study-notes.txt`,`${L.title}\n\nParagraphs read: ${state.read.join(', ')}\n\nClosed-book recall\n${L.recall.map(q=>'R'+q.id+': '+(state.recall[q.id]||'Not attempted')+(state.recalled.includes(q.id)?' · Self-marked recalled':'')).join('\n')}\n\nBookmarked vocabulary\n${L.vocabulary.filter(v=>state.saved.includes(v.id)).map(v=>v.word+' — '+N.vocabulary[Number(v.id)-1]+'\n'+v.Collocation).join('\n\n')}\n\nReading answers\n${L.reading.map(q=>q.id+'. '+(state.answers[q.id]||'Not answered')).join('\n')}\n\nVocabulary practice\n${L.practice.map(q=>q.id+'. '+(state.practice[q.id]||'Not answered')).join('\n')}\n\nWriting\n${state.writing}\n\nChallenge response\n${state.challenge}\n\nSpeaking notes\n${L.speaking.map((s,i)=>s.title+'\n'+(state.speaking[i]||'')).join('\n\n')}`);
    else if(action==='flashcards')flashcard();
    else if(action==='flash-reveal')flashcard(Number(el.dataset.index),true);
    else if(action==='flash-next')flashcard(Number(el.dataset.index));
    else if(action==='source')openDialog('Original lesson and reference material',`<div class="source-intro"><p>Lesson date · ${L.date} · Day ${L.day}</p><a href="${L.sourceFile}" download class="button secondary compact">${icon('download')} Download the complete Markdown lesson</a></div><div class="prose"><h2>Distinguish evidence from judgement</h2><p>${inline((L.sections[L.title].split(/\*\*Evidence (?:lens|note):\*\*/)[1] || '').trim())}</p><h2>Sources and further reading</h2>${markdown(L.sections['SOURCES AND FURTHER READING'])}</div>`,'source-dialog');
  });
  app.addEventListener('input',event=>{
    const el=event.target;
    if(el.dataset.recall){state.recall[el.dataset.recall]=el.value;save();}
    if(el.dataset.coverage){updateCoverage();}
    if(el.id==='vocab-search'){search=el.value;document.querySelector('#vocab-list').innerHTML=wordList();}
    if(el.name?.match(/^q\d+$/)){state.answers[el.name.slice(1)]=el.value;state.submitted=false;save();document.querySelector('#answer-progress').textContent=`Answered ${Object.values(state.answers).filter(Boolean).length} / 15`;document.querySelectorAll('.feedback').forEach(f=>f.hidden=true);document.querySelector('#reading-score').textContent='';}
    if(el.dataset.practice){state.practice[el.dataset.practice]=el.value;save();}
    if(el.dataset.speaking){state.speaking[el.dataset.speaking]=el.value;save();}
    if(el.id==='writing-editor'){state.writing=el.value;save();document.querySelector('#writing-count').textContent=wordCount(el.value)+' words';document.querySelector('#writing-save-status').textContent='Saved in this browser';}
    if(el.id==='challenge-editor'){state.challenge=el.value;save();document.querySelector('#challenge-count').textContent=wordCount(el.value)+' words';updateChallenge();}
    if(['wage-range','price-range'].includes(el.id)){const wage=Number(document.querySelector('#wage-range').value),price=Number(document.querySelector('#price-range').value),real=((1+wage/100)/(1+price/100)-1)*100;document.querySelector('#wage-label').textContent=wage+'%';document.querySelector('#price-label').textContent=price+'%';const result=document.querySelector('#real-change');result.textContent=(real>0?'+':real<0?'−':'')+Math.abs(real).toFixed(2)+'%';result.classList.toggle('positive',real>0);document.querySelector('#real-meaning').textContent=real>0?'Wages have outpaced prices, so purchasing power has increased.':real<0?'Pay has risen, but it buys less.':'Wages and prices have risen at the same rate; purchasing power is unchanged.';}
  });
  app.addEventListener('submit',event=>{if(event.target.id==='reading-form'){event.preventDefault();state.submitted=true;save();L.reading.forEach(q=>{const f=document.querySelector('#feedback-'+q.id);f.innerHTML=answerFeedback(q);f.hidden=false;});document.querySelector('#reading-score').textContent=scoreText();toast('Answers checked. Follow a paragraph link to review the evidence.');}});
  window.addEventListener('hashchange',()=>route());
  window.addEventListener('wordbook-change',()=>{
    syncSaved();
    document.querySelectorAll('[data-action="save-word"]').forEach(b=>{const v=L.vocabulary.find(v=>v.id===b.dataset.id);if(!v)return;const saved=state.saved.includes(v.id);b.classList.toggle('saved',saved);b.setAttribute('aria-pressed',saved);b.setAttribute('aria-label',(saved?'Remove bookmark ':'Bookmark ')+v.word);});
    if(current==='review')document.querySelector('#main').innerHTML=review();
    if(current==='vocabulary'&&filter==='saved')document.querySelector('#vocab-list').innerHTML=wordList();
  });
  document.addEventListener('keydown',event=>{if(event.key==='Escape')closeNav();if(event.key==='Tab'&&document.body.classList.contains('nav-open')){const focusable=[...document.querySelectorAll('.sidebar a,.sidebar button')].filter(el=>el.getClientRects().length);const first=focusable[0],last=focusable.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus();}}});
  shell();route(false);
})();
